"use client";

import { useEffect, useLayoutEffect, useState, type RefObject } from "react";
import { placePopup } from "../_internal/position";

// Shared helpers for the floating overlays (Popover, HoverCard, Menubar):
// keep a portalled panel placed against its anchor while it is open, and
// close it on Esc or a press outside both.

export type FloatSide = "bottom" | "top";
export type FloatAlign = "start" | "center" | "end";

/** Places `popup` against `anchor` on open, then on every scroll and resize. */
export function useFloatingPlacement(
  open: boolean,
  anchorRef: RefObject<HTMLElement | null>,
  popupRef: RefObject<HTMLElement | null>,
  opts: { side?: FloatSide; align?: FloatAlign; offset?: number; enabled?: boolean } = {},
) {
  const { side = "bottom", align = "start", offset = 8, enabled = true } = opts;
  useLayoutEffect(() => {
    if (!open || !enabled) return;
    const place = () => {
      const a = anchorRef.current;
      const p = popupRef.current;
      if (a && p) placePopup(a, p, { side, align, offset });
    };
    place();
    window.addEventListener("scroll", place, true);
    window.addEventListener("resize", place);
    return () => {
      window.removeEventListener("scroll", place, true);
      window.removeEventListener("resize", place);
    };
  }, [open, enabled, side, align, offset, anchorRef, popupRef]);
}

/** Esc and a pointer press outside every given element call onDismiss. */
export function useDismiss(
  open: boolean,
  refs: ReadonlyArray<RefObject<HTMLElement | null>>,
  onDismiss: (reason: "escape" | "outside") => void,
  enabled = true,
) {
  useEffect(() => {
    if (!open || !enabled) return;
    const onDown = (e: PointerEvent) => {
      const t = e.target as Node | null;
      if (t && refs.some((r) => r.current?.contains(t))) return;
      onDismiss("outside");
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.stopPropagation();
      onDismiss("escape");
    };
    document.addEventListener("pointerdown", onDown, true);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onDown, true);
      document.removeEventListener("keydown", onKey);
    };
    // refs are stable ref objects.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, enabled, onDismiss]);
}

/** Controlled or uncontrolled open state, the shadcn way. */
export function useOpenState(open: boolean | undefined, defaultOpen: boolean | undefined, onOpenChange?: (open: boolean) => void) {
  const [inner, setInner] = useState(Boolean(defaultOpen));
  const value = open ?? inner;
  const set = (next: boolean) => {
    if (open === undefined) setInner(next);
    onOpenChange?.(next);
  };
  return [value, set] as const;
}

/* Popover: the frosted popover family (Select, Menu) holding arbitrary
   content. Every surface value is a --popover-* token, so the flat and dark
   presets restyle it with no change here. */

.panel {
  min-width: var(--popover-min-width, 220px);
  max-width: min(var(--popover-max-width, 380px), calc(100vw - 16px));
  padding: var(--popover-content-pad, calc(16px * var(--density)));
  background: var(--popover-surface);
  -webkit-backdrop-filter: var(--popover-blur);
  backdrop-filter: var(--popover-blur);
  border: var(--border-w) solid var(--popover-border);
  border-radius: var(--popover-radius, var(--r-lg));
  box-shadow: var(--popover-shadow);
  color: var(--ink-body);
  font-size: var(--text-small);
  line-height: 1.5;
}

.panel:focus-visible {
  outline: none;
  box-shadow: var(--popover-shadow), var(--focus-ring);
}

.floating {
  position: fixed;
  z-index: var(--z-popover);
  animation: pop-in var(--dur-slow) var(--ease-out);
}

/* Inline: the trigger, then the open panel under it, in the page flow. */
.inlineWrap {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
}

.alignEnd {
  align-items: flex-end;
}

.alignCenter {
  align-items: center;
}

.inline {
  position: relative;
}

@media (prefers-reduced-motion: reduce) {
  .floating {
    animation: fade-in var(--dur) linear;
  }
}

"use client";

import {
  cloneElement,
  isValidElement,
  useCallback,
  useEffect,
  useId,
  useRef,
  type MouseEvent,
  type ReactElement,
  type ReactNode,
  type Ref,
} from "react";
import { cx } from "../_internal/cx";
import { mergeRefs } from "../_internal/merge-refs";
import { Portal } from "../_internal/portal";
import { focusableWithin } from "../_internal/position";
import { useDismiss, useFloatingPlacement, useOpenState, type FloatAlign, type FloatSide } from "./floating";
import styles from "./Popover.module.css";

type TriggerProps = {
  ref?: Ref<HTMLElement>;
  onClick?: (e: MouseEvent<HTMLElement>) => void;
  "aria-expanded"?: boolean;
  "aria-haspopup"?: "dialog";
  "aria-controls"?: string;
};

export type PopoverProps = {
  /** The button that opens it. Gets aria-expanded, aria-controls and the click handler. */
  trigger: ReactElement<TriggerProps>;
  /** The panel's content: a short form, a set of filters, a details block. */
  children: ReactNode;
  /** The panel's accessible name ("Edit dimensions"). Use it when the content has no heading. */
  label?: string;
  /** Controlled open state. Leave unset for uncontrolled. */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Preferred side; flips when there is no room. */
  side?: FloatSide;
  align?: FloatAlign;
  /** Panel width in px. Defaults to the content's width (min 220px). */
  width?: number;
  /**
   * Render the open panel in the page flow under the trigger: not portalled,
   * no outside-click or Esc handling. For docs, previews and static mock-ups.
   */
  inline?: boolean;
  className?: string;
};

/**
 * An anchored floating panel for arbitrary content. Click the trigger to
 * open; Esc or a press outside closes it and returns focus to the trigger.
 * Focus moves to the first focusable element inside (or the panel itself),
 * but is not trapped: Tab out and the panel stays until dismissed.
 */
export function Popover({
  trigger,
  children,
  label,
  open: openProp,
  defaultOpen,
  onOpenChange,
  side = "bottom",
  align = "start",
  width,
  inline,
  className,
}: PopoverProps) {
  const [open, setOpen] = useOpenState(openProp, defaultOpen, onOpenChange);
  const id = useId();
  const anchorRef = useRef<HTMLElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);

  useFloatingPlacement(open, anchorRef, panelRef, { side, align, enabled: !inline });

  const close = useCallback(
    (reason: "escape" | "outside") => {
      setOpen(false);
      if (reason === "escape") anchorRef.current?.focus();
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [openProp, onOpenChange],
  );
  useDismiss(open, [anchorRef, panelRef], close, !inline);

  // Move focus in on open.
  useEffect(() => {
    if (!open || inline) return;
    const frame = requestAnimationFrame(() => {
      const p = panelRef.current;
      if (!p) return;
      (focusableWithin(p)[0] ?? p).focus();
    });
    return () => cancelAnimationFrame(frame);
  }, [open, inline]);

  const triggerEl = isValidElement(trigger)
    ? cloneElement(trigger, {
        ref: mergeRefs(trigger.props.ref, anchorRef),
        "aria-expanded": inline ? true : open,
        "aria-haspopup": "dialog",
        "aria-controls": open || inline ? id : undefined,
        onClick: (e: MouseEvent<HTMLElement>) => {
          trigger.props.onClick?.(e);
          if (!e.defaultPrevented && !inline) setOpen(!open);
        },
      })
    : trigger;

  const panel = (
    <div data-slot="popover"
      ref={panelRef}
      id={id}
      role="dialog"
      aria-label={label}
      tabIndex={-1}
      className={cx(styles.panel, inline ? styles.inline : styles.floating, className)}
      style={width ? { width } : undefined}
    >
      {children}
    </div>
  );

  if (inline) {
    return (
      <div className={cx(styles.inlineWrap, align === "end" && styles.alignEnd, align === "center" && styles.alignCenter)}>
        {triggerEl}
        {panel}
      </div>
    );
  }

  return (
    <>
      {triggerEl}
      {open ? <Portal>{panel}</Portal> : null}
    </>
  );
}
